var host = UnityEngine.Object.FindObjectOfType<Hotfix.GameSystems.SyncLayer.ClientNetworkHost>();
if (host == null) { Debug.Log("[G] NO HOST"); return; }
var reg = host.RemoteEntities;
if (reg == null) { Debug.Log("[G] NO REGISTRY"); return; }
var terrainGo = GameObject.Find("LowpolyTerrain");
if (terrainGo == null) { Debug.Log("[G] NO TERRAIN"); return; }
var ids = new System.Collections.Generic.List<long>(reg.PlayerIds);
int npc = 0;
float maxDelta = 0f;
foreach (var id in ids)
{
    var view = reg.GetView(id);
    if (view == null || view.Kind != (byte)Cool.Protocol.EntityKind.Npc) continue;
    npc++;
    var p = view.Position;
    var ray = new Ray(new Vector3(p.x, 200f, p.z), Vector3.down);
    var hits = Physics.RaycastAll(ray, 400f);
    float groundY = float.NaN;
    float bestTerr = float.MaxValue;
    float bestAny = float.MaxValue;
    float naiveY = float.NaN;
    string naiveName = "-";
    for (int i = 0; i < hits.Length; i++)
    {
        if (hits[i].distance < bestAny) { bestAny = hits[i].distance; naiveY = hits[i].point.y; naiveName = hits[i].collider.gameObject.name; }
        var t = hits[i].collider.transform;
        if ((t == terrainGo.transform || t.IsChildOf(terrainGo.transform)) && hits[i].distance < bestTerr)
        { bestTerr = hits[i].distance; groundY = hits[i].point.y; }
    }
    float delta = Mathf.Abs(p.y - groundY);
    if (delta > maxDelta) maxDelta = delta;
    Debug.Log("[G] npc id=" + id + " xz=(" + p.x.ToString("F2") + "," + p.z.ToString("F2") + ") viewY=" + p.y.ToString("F3") + " groundY=" + groundY.ToString("F3") + " delta=" + delta.ToString("F4") + " | naiveFirstHit=" + naiveName + " y=" + naiveY.ToString("F3"));
}
Debug.Log("[G] SUMMARY npcViews=" + npc + " views=" + reg.Count + " maxDelta=" + maxDelta.ToString("F4") + " playing=" + Application.isPlaying);
